import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.sql.*;
public class ViewCustomerFrame extends JFrame{JTable table;DefaultTableModel model;public ViewCustomerFrame(){setTitle("Banking Management System - VIEW CUSTOMERS");setSize(1050,520);setLocationRelativeTo(null);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel p=new JPanel(new BorderLayout());p.setBackground(new Color(230,240,255));JLabel h=new JLabel("VIEW CUSTOMERS",SwingConstants.CENTER);h.setFont(new Font("Arial",1,22));h.setBorder(BorderFactory.createEmptyBorder(15,10,15,10));p.add(h,BorderLayout.NORTH);String[] cols={"ID","NAME","PHONE","EMAIL","ADDRESS"};model=new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);p.add(new JScrollPane(table),BorderLayout.CENTER);JButton r=new JButton("REFRESH"),c=new JButton("CLOSE");JPanel bp=new JPanel();bp.add(r);bp.add(c);p.add(bp,BorderLayout.SOUTH);r.addActionListener(e->load());c.addActionListener(e->dispose());add(p);load();}void load(){model.setRowCount(0);try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement("SELECT CUSTOMER_ID,CUSTOMER_NAME,PHONE,EMAIL,ADDRESS FROM BANK_CUSTOMERS ORDER BY CUSTOMER_ID");ResultSet r=q.executeQuery()){while(r.next())model.addRow(new Object[]{r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5)});}catch(SQLException e){JOptionPane.showMessageDialog(this,"Database Error: "+e.getMessage());}}}
